function bitmaskIsFree(int $scheduleMask, array $bookingMasks, int $requestedMask): bool
{
    $booked = 0;
    foreach ($bookingMasks as $mask) {
        $booked |= $mask;
    }
    return (($scheduleMask & ~$booked) & $requestedMask) === $requestedMask;
}

private int calculatePriorityPoints(Task task) {
    int difficultyPoints = calculateDifficultyPoints(task.getDifficulty());

    int daysLeft = Period.between(LocalDate.now(), task.getDueDate()).getDays();
    int urgencyPoints = Math.max(0, 30 - daysLeft);

    int timeFitPoints = task.getTimeAllotted() < 5 ? 5 : 2;
    int timeRemainingScore = Math.max(0, daysLeft);

    return difficultyPoints + urgencyPoints + timeFitPoints - timeRemainingScore;
}

fn chanceValue(ctx: *const Context, branches: *const Branches, plies_left: u32) f32 {
    node_count += 1;
    const score_a = branchValue(ctx, &branches.a, branches.prev_lines, plies_left);
    const score_b = branchValue(ctx, &branches.b, branches.prev_lines, plies_left);
    return (branches.prob_a * score_a) + ((1.0 - branches.prob_a) * score_b);
}

